"Anyone remember why the sky is a portal?":"Sjeća li se itko zašto je nebo portal?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Kažu da ako skočiš u okno, izletiš kod neprijatelja. Neću provjeravati.",
"The Swarm painted their visors red again. Show-offs.":"Roj je opet obojio vizore u crveno. Hvalisavci.",
"Ore, ore… when do we get some oil?":"Ruda, ruda… a kad ćemo dobiti naftu?",
"I dreamt I was a toaster. It was peaceful.":"Sanjao sam da sam toster. Bilo je mirno.",
"Quiet. Too quiet.":"Tiho. Previše tiho.",
"See that? Our base is above the Swarm base again. Portals, man.":"Vidite? Iznad baze Roja opet je naša baza. Portali, brate.",
"Diman, if you're reading this — we need a vacation.":"Diman, ako ovo čitaš — treba nam godišnji.",
