"Autosaved":"Automatski spremljeno",
"robot war · the sky is a portal":"rat robota · nebo je portal",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Dobro došao na meteor! Ti si borbeni robot Konzorcija. Gledaj oko sebe mišem i kreći se tipkama WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Jetpack: dodirni Shift za skok, drži Shift za let. Energija se obnavlja na tlu.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Pucaj — lijeva tipka miša. Nišan — desna tipka miša: preciznije i s zumom. Ispali nekoliko hitaca.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Punjenje — R. Meci najjače pogađaju na srednjoj udaljenosti, 20–50 metara.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Raketa — Q. Protiv tenkova i zgrada. Ispali raketu.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Na vrhu je zapovijed AI stratega. Trči po zelenim strelicama: na ruti imaš sprint. Zauzmi točku — stani kraj signalnog svjetionika.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Tvoj odred te pokriva: njihovi portreti i zdravlje su lijevo. Ako zaostanu, zamolit će te da pričekaš.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — brza zamjena jedinice bez izlaska iz borbe: skoči u odred ili tenk najbliži okršaju. Isprobaj.",
"Next to a tank or turret press E to take control. Or just carry on.":"Pokraj tenka ili kupole pritisni E za preuzimanje kontrole. Ili samo nastavi dalje.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Sad strategija. Dodirni \"◩ Strategija\" gore desno — pogled odozgo na bojište.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Sad strategija. Pritisni {0} (ili \"◩ Strategija\" gore lijevo) — pogled odozgo na bojište.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"U strategiji ti pomaže Kurator: kutija gore kaže što učiniti, okvir pokazuje tipku, prsten označava mjesto na karti. Izvrši tri njegova savjeta.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Odaberi odred i dodirni zelenu tipku \"▶ Preuzmi\" — natrag u borbu kao taj vojnik. Dok ti pucaš, AI strateg sam zapovijeda vojskom.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Odaberi odred i pritisni {0} ili zelenu \"▶ Preuzmi\" — natrag u borbu kao taj vojnik (ako ništa nije odabrano — svoj). Dok ti pucaš, AI strateg sam zapovijeda vojskom.",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"Trening završen! Roj počinje ofenzivu. Sretno, vojniče!",
