"The heavy MG is a reward the strategist hands out for completed orders.":"Teški mitraljez strateg daje kao nagradu za izvršene zapovijedi.",
"{0} unlocks at rank \"{1}\". XP comes from kills, captures and strategist orders (×2–×3).":"{0} se otključava na činu \"{1}\". Iskustvo donose ubojstva, zauzimanje točaka i zapovijedi stratega (×2–×3).",
"Left thumb — move, right thumb — look. Red button — fire.":"Lijevi palac — kretanje, desni — pogled. Crvena tipka — paljba.",
"⇑ — jetpack: tap to hop, hold to fly. ◎ — aim.":"⇑ — jetpack: dodir za skok, drži za let. ◎ — nišan.",
"In the air, ⤓ is the jet brake.":"U zraku ⤓ je kočnica jetpacka.",
"Move and shoot: mouse to look, LMB to fire.":"Kreći se i pucaj: miš — pogled, lijeva tipka miša — paljba.",
"At the top is the AI strategist's order. Follow it: ×2 and ×3 XP, and completed orders can earn rewards. The green marker and chevrons lead the way.":"Gore je zapovijed AI stratega. Slijedi je: ×2 i ×3 iskustva, a za izvršenje ima i nagrada. Zeleni marker i strelice vode do cilja.",
"Shift — jump pack: tap to hop, hold to fly. RMB — aim.":"Shift — jetpack: dodir za skok, drži za let. desna tipka miša — nišan.",
"In the air, C is the jet brake. Stop, turn with the mouse and thrust again.":"U zraku je C kočnica jetpacka. Zakoči, okreni se pogledom i opet daj potisak.",
"Enemy vehicle or structure nearby. A rocket is best against them.":"U blizini je neprijateljsko vozilo ili građevina. Raketa je najbolja protiv njih.",
"Enemies are bunched up — throw a grenade.":"Neprijatelji su se zbili — baci granatu.",
"Lots of hostiles — trigger Reflex: time slows down and you can pick them off.":"Puno neprijatelja — uključi refleks: vrijeme uspori, a ti ih stigneš sve skinuti.",
"Aim at the enemy cluster and call in a strike.":"Naciljaj skupinu neprijatelja i pozovi udar.",
"Targets are far — the railgun is stronger at long range.":"Mete su daleko — railgun je jači na velikoj udaljenosti.",
"You have a temporary heavy MG — use it before it is recalled.":"Imaš privremeni teški mitraljez — koristi ga prije nego ga povuku.",
"Parkour: C while running — slide, jump at a ledge — climb it, jump next to a wall in the air — wall-jump.":"Parkour: C u trku — klizanje, skok kraj ruba — penjanje, skok kraj zida u zraku — odskok od zida.",
"Bullets hit hardest at 20–50 m. Point-blank and long range are much weaker — for enemies too.":"Meci najjače pogađaju na 20–50 m. Iz blizine i izdaleka znatno slabije — i po tebi također.",
"Your robot is badly damaged. Get out of the fire — armor self-repairs out of combat.":"Tvoj robot je teško oštećen. Izađi iz vatre — izvan borbe se oklop sam popravlja.",
"One of our tanks is close. Walk up and press E to take control.":"Blizu je naš tenk. Priđi i pritisni E — upravljat ćeš njime.",
"Man the turret — press E next to it.":"Zauzmi kupolu — E pokraj nje.",
"It is quiet here. Switch to a squad or vehicle closer to the fight.":"Ovdje je mirno. Prebaci se na odred ili vozilo bliže borbi.",
"Reload early while no enemies are around.":"Ponovno napuni unaprijed, dok nema neprijatelja.",
"Sprint right along the strategist's green chevrons — you run faster on his route.":"Trči točno po zelenim strelicama stratega — na njegovoj ruti trčiš brže.",
"\"◩ Strategy\" button — top view: build the base, order troops, command squads.":"Tipka \"◩ Strategija\" — pogled odozgo: gradi bazu, naručuj vojsku, zapovijedaj odredima.",
"Strategy mode: build the base, order troops, call strikes and command squads. The same key there possesses the selected unit.":"Način strategije: gradi bazu, naručuj vojsku, pozivaj udare i zapovijedaj odredima. Ista tipka tamo znači preuzeti odabranu jedinicu.",
"Want full command? Turn off the AI strategist — then you give the orders.":"Želiš zapovijedati sam? Isključi AI stratega — tada ti izdaješ zapovijedi.",
"Third-person view — to see your robot.":"Pogled iz trećeg lica — da vidiš svog robota.",
"Tank: {0} — barrage at your aim point, {1} — smoke screen, {2} — overdrive. {3} — back to infantry.":"Tenk: {0} — plotun u točku nišana, {1} — dimna zavjesa, {2} — overdrive. {3} — natrag u pješaštvo.",
"Plenty of targets — fire a barrage.":"Mnogo meta — ispali plotun.",
"Drone: {0}/{1} — up/down, LMB — fire, {2} — ram your aim point.":"Dron: {0}/{1} — gore/dolje, lijeva tipka miša — paljba, {2} — ramanje točke nišana.",
"Select a squad — LMB, drag a box or a card on the left. RMB on the ground — attack-move ⚔, on an enemy — attack, on a point — capture.":"Odaberi odred — lijeva tipka miša, okvirom ili karticom lijevo. Desna tipka miša po tlu — napadni pokret ⚔, po neprijatelju — napad, po točki — zauzimanje.",
"Squads have abilities: grenades, jet leap, suppression, repair. Tanks: barrage, smoke, overdrive.":"Odredi imaju sposobnosti: granate, skok jetpackom, potiskivanje, popravak. Tenkovi: plotun, dim, overdrive.",
"Plenty of ore — select the HQ or a factory and order troops in its panel on the right.":"Ima dosta rude — odaberi stožer ili tvornicu i naruči vojsku u njezinoj ploči desno.",
"Command points are piling up — \"Powers\" tab: recon, artillery, squad drop pod, orbital strike.":"Gomilaju se zapovjedni bodovi (ZB) — kartica \"Udari\": izviđanje, topnički udar, kapsula s odredom, orbitalni udar.",
"Only builders construct buildings: select a builder (button in the Build tab or a building key), then click the spot. An extractor (C) on a glowing vein — more ore.":"Zgrade grade samo inženjeri: odaberi inženjera (tipka u kartici \"Gradnja\" ili tipka zgrade), zatim klikni na mjesto. Ekstraktor (C) na užarenoj žili — više rude.",
"Click \"ORE\" at the top left — where ore comes from and how to boost income.":"Klikni na \"RUDA\" gore lijevo — odakle dolazi ruda i kako ubrzati prihod.",
"Ctrl+1…9 — save a group, 1…9 — select it, double-tap — jump the camera.":"Ctrl+1…9 — spremi skupinu, 1…9 — odaberi je, dvostruki pritisak — kamera na nju.",
"Select a unit and tap the green \"▶ Possess\" below (or double tap) to fight yourself. \"◩ Strategy\" brings you back.":"Odaberi jedinicu i dodirni zelenu \"▶ Preuzmi\" dolje (ili dvostruki dodir) da se boriš sam. \"◩ Strategija\" te vraća natrag.",
"Select a unit and press the green \"▶ Possess\" below or {0} (or double-click) to fight yourself. In battle {1} brings you back.":"Odaberi jedinicu i pritisni zelenu \"▶ Preuzmi\" dolje ili {0} (ili dvostruki klik) — boriš se sam. U borbi te {1} vraća natrag.",
"Grey buttons can be pressed too: you will see what is missing, how long to wait and how to fix it.":"I sive tipke se mogu pritisnuti: pokazat ćemo što nedostaje, koliko čekati i kako to popraviti.",
"RMB on the ground — rally point for this building's new troops.":"Desna tipka miša po tlu — točka okupljanja za novu vojsku ove zgrade.",
"RMB — attack-move ⚔: they stop to fight enemies they meet, then continue. Double RMB — march »: run without stopping, firing on the move. Hold/Retreat — \"More orders ▾\".":"Desna tipka miša — napadni pokret ⚔: kad sretnu neprijatelja, zaustave se i bore, pa idu dalje. Dvostruka desna tipka miša — marš »: trče bez zaustavljanja, pucajući u pokretu. Zadrži/Povuci se — \"Više zapovijedi ▾\".",
"Camera: drag with a finger, two fingers — zoom and rotate, drag on the minimap too.":"Kamera: povuci prstom, dva prsta — zumiranje i rotacija, minikartu također možeš vući prstom.",
"Camera: WASD and screen edges, Q/E rotate, wheel zoom (to cursor), MMB orbit, minimap — click or drag, Space — to the latest alert.":"Kamera: WASD i rubovi ekrana, Q/E — rotacija, kotačić — zum (prema kursoru), srednja tipka miša — kruženje, minikarta — klik ili povlačenje, Razmaknica — do zadnjeg alarma.",
