"New in v6.3":"Novo u v6.3",
"New in v6.2":"Novo u v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Novi izgled rude: žile su sjajni smaragdni brušeni kristali na crnom bazaltu s iskrama i zelenom izmaglicom; ekstraktor je šesterokutni postament sa saćastom kupolom i rešetkastim tornjem s zelenim svjetionikom na vrhu (traka i zastavica u boji tima)",
"New in v6.1":"Novo u v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Omiljena klasa kao u Battlefieldu (U, brojke nakon pogibije): vraćaš se u igru s njom kad je dostupna",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Tehnika iz prvog lica (V — izvana/iz kabine); blago pomaganje pri ciljanju — u Postavkama",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Lakši izlaz iz Jezgre: Razmaknica — do okna, B — kapsula na površinu; učinci sposobnosti resetiraju se pri pogibiji",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Beskonačno napredovanje: generali i Maršal ★, razine karijere, majstorstvo oružja i dodaci, medalje, dnevni ugovori — zaslon „Karijera”",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Strategija: glatki zoom kotačićem, ikone i oznake iznad jedinica (Alt — sve), ploča „Trupe / Zgrade” slijeva",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"desna tipka miša — napad u hodu, dvostruka desna tipka miša — marš uz paljbu u pokretu; rijetke naredbe — u „Više naredbi ▾”; gumbi se ne dupliciraju",
"New in v6":"Novo u v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Pucanje kao u pucačinama: trenutni meci, automat 720 met/min, mitraljez, trzaj, nišan na desnu tipku miša, spremnici i ponovno punjenje R, oznake pogodaka",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Teža gravitacija, odzivni jetpack, nalet na Z ili 2× jetpack u zraku; pri prelasku u drugog borca oružje više ne leti za tobom",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Inženjeri: odaberi inženjera, odaberi zgradu, postavi nacrt; ekstraktori na žilama rude; klik na „RUDA” — odakle dolazi prihod i kako ga ubrzati",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Sive gumbe možeš pritisnuti — pokazat ćemo zašto ne rade i ponuditi rješenje; veći gumbi, traka „U tijeku”, „▶ Preuzmi”, Tab je jedina tipka načina",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Kamera strategije bez trzaja i prevrtanja, zoom prema kursoru, minikartu možeš povlačiti",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Nova tehnika: raider „Šakal”, raketni bacač „Grad” (rakete s navođenjem), minobacač „Malj”; Swarm dobiva „Osu”, „Košnicu”, „Trebuše”",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Strateg ne mijenja naredbe i ne spama glasom; borbe su blizu tebe; B — premještaj, Shift+B — u središte borbe; kompas, H — koja meta",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Slobodna igra (K) i „djelujem sam” (J), F2 — predlošci; Esc — pauza i povratak; spremanja: utori, izvoz i uvoz datoteke",
"New in v5.3":"Novo u v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Let: gravitacija je jača daleko od meteora, C u zraku — kočnica, potisak upravlja oštrije; više nećeš „visjeti” u portalu",
"New in v5":"Novo u v5",
"Endless war by default and battle scale: normal, large, epic":"Beskonačna borba prema zadanim postavkama i razmjer bitaka: običan, veliki, epski",
"Save and load the battle (autosave every 3 minutes)":"Spremanje i učitavanje borbe (i automatsko spremanje svake 3 minute)",
"Squadmates with callsigns: portraits, health and live chatter":"Odred s pozivnim znakovima: portreti, zdravlje i žive razmjene",
"Fog of war in strategy, friends and foes outlined differently":"Magla rata u strategiji, saveznici i neprijatelji istaknuti različito",
"Camera fly-over when switching, portal aurora instead of rings":"Preletna kamera pri prebacivanju, sjaj portala umjesto prstenova",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Sporedni zadaci, prečac kroz nebo, moduli prve ekspedicije sa zalihama, kristali, led u kraterima, prašinske oluje",
"Training, cinema mode with video recording, escort vehicles from the strategist":"Trening, filmski način sa snimanjem videa, pratnja tehnikom od stratega",
