"Grenades: hold G for the flight arc, blast point and radius, distance; release to throw. Range by view angle, wheel — power, RMB — underhand":"Granate: drži G — luk leta, točka i krug eksplozije, udaljenost; pusti — bacanje. Domet kutom pogleda, kotačić — snaga, desna tipka miša — ispod ruke",
"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"Granata se odbija i kotrlja niz padinu, eksplozija nakon 2.5 s; 2 granate, obnova 9 s; ikona upozorenja o neprijateljskoj granati u blizini",
