"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"Granata ({0}): drži — luk leta, točka i krug eksplozije, udaljenost; pusti — bacanje; kratki dodir odmah baca. Domet kutom pogleda, kotačić — snaga, desna tipka miša — bacanje odozdo. Telefon: drži G i povuci prstom.",
