"The Consortium heavy gunner is now a real rigged 3D model: idles, walks, charges with his gun, fires on the move and falls when destroyed":"Teški strijelac Konzorcija sada je prava 3D-model sa skeletom: stoji, hoda, trči s oružjem, puca u hodu i lijepo pada kad bude uništen",
"The model follows the meteor surface normal, turns its torso to aim and holds the machine gun; far away the animation updates less often to keep FPS":"Model stoji okomito na površinu meteora, okreće trup prema nišanu i drži mitraljez; iz daljine se animacija rjeđe osvježava — FPS ne pada",
