"Infantry: assault squads, heavy gunners, snipers, scouts, drop pods; armor and weapon upgrades.":"Pješaštvo: jurišni odredi, teški strijelci, snajperisti, izviđači, desantne kapsule; poboljšanja oklopa i oružja.",
"Ore depot":"Skladište rude",
"Builders drop crystals here. Place it next to a crystal field — shorter trips, more ore.":"Ovdje inženjeri predaju kristale. Postavi ga uz kristalno polje — kraći put, više rude.",
"Tanks and vehicles. Requires Barracks.":"Tenkovi i vozila. Potrebna je Vojarna.",
"Autonomous combat drones. Requires Barracks.":"Autonomni borbeni dronovi. Potrebna je Vojarna.",
"Jetpacks II and Sky troopers (jetpack elite). Requires a Mech factory, unlocks at 6:00.":"Jetpackovi II i Nebeski desant (elita s jetpackovima). Potrebna je tvornica mehova, otključava se u 6:00.",
"Forward base at an owned point: builders, crystal drop-off, reinforcement.":"Predstraža kod tvoje točke: inženjeri, predaja kristala, pojačanja.",
