"Heavy bunker with AT gun":"Teški bunker s protutenkovskim topom",
"A second bunker with an anti-tank gun (vehicles out to 110 m); the pillbox gets armour plates and the outpost +35% HP.":"Drugi bunker s protutenkovskim topom (vozila do 110 m), bunker dobiva oklopne ploče, a predstraža je 35 % čvršća.",
"Support":"Potpora",
"Repair-drone bay":"Hangar popravnih dronova",
"Three repair drones fix friendly robots, vehicles and buildings within 28 m.":"Tri drona-popravljača popravljaju savezničke robote, vozila i zgrade u radijusu od 28 m.",
"Force-field dome":"Kupola sile",
"A 24 m dome: friendlies inside take 38% less damage.":"Kupola radijusa 24 m: saveznici unutar nje primaju 38 % manje štete.",
"Recon":"Izviđanje",
"Radio scanner":"Radiosken",
"A scanner mast clears the fog of war within 150 m.":"Jarbol sa skenerom uklanja maglu rata u krugu od 150 m.",
"Sniper & spotter tower":"Snajperski toranj-korektor",
"Vision 190 m, marks enemies for the whole army (160 m), artillery and MLRS are twice as accurate there, and a sniper on top shoots infantry.":"Vidokrug 190 m, označava neprijatelje za cijelu vojsku (160 m), topništvo i višecijevni bacači raketa tamo gađaju dvostruko preciznije, a snajperist na tornju gađa pješaštvo.",
"Armour plating":"Oklopne ploče",
"HQ +50% HP and −25% damage taken.":"Stožer +50 % čvrstoće i −25 % primljene štete.",
"Defence turrets":"Obrambene kupole",
"4 twin turrets on the HQ platform: infantry, drones and light vehicles within 95 m.":"4 dvocijevne kupole na platformi stožera: pješaštvo, dronovi i laka vozila do 95 m.",
"Faster orbital drop":"Ubrzano orbitalno spuštanje",
"A homing beacon: squads and solos from the barracks, builders and the drop pod are 35% faster, the pod is 25% cheaper.":"Radiofar za navođenje: odredi i pojedinci iz vojarne, inženjeri i desantna kapsula spremni su 35 % brže, a kapsula je 25 % jeftinija.",
"Ore refinery columns":"Rudne obogaćivačke kolone",
"Income +25%.":"Prihod +25 %.",
"Global radar":"Globalni radar",
"Every 40 s a pulse reveals every enemy on the meteor for 6 s.":"Svakih 40 s — impuls: svi neprijatelji na meteoru vidljivi su 6 s.",
"Comms array":"Komunikacijske antene",
"+2 command points now and +1 more every 40 s (strikes, strategist powers).":"+2 zapovjedna boda odmah i još +1 svakih 40 s (udari, sposobnosti stratega).",
