"Point {0}: orbit is dropping a pod — a squad{1}":"Točka {0}: orbita spušta kapsulu — odred{1}",
"Pod on point {0}: {1}{2}{3}. The builder can place an outpost (V) and pick an upgrade branch.":"Kapsula na točki {0}: {1}{2}{3}. Inženjer može postaviti predstražu (V) i odabrati granu nadogradnji.",
"HQ radar: every enemy is visible for 6 s":"Radar stožera: svi neprijatelji vidljivi su 6 s",
"HQ upgrades":"Nadogradnje stožera",
"Built":"Izgrađeno",
"Building — click to cancel (refund)":"Gradi se — klik: otkaži (ruda se vraća)",
"Outpost upgrades":"Nadogradnje predstraže",
"point":"točka",
"Pick a branch — every point gets its own speciality:":"Odaberi granu — svaka točka ima svoju specijalizaciju:",
"Building — click to cancel":"Gradi se — klik: otkaži",
"A builder near the outpost (30 m) does the upgrade.":"Nadogradnju gradi inženjer pokraj predstraže (30 m).",
"Send a builder":"Pošalji inženjera",
"Builders nearby":"Inženjera u blizini",
"{0} is heading to the outpost":"{0} ide prema predstraži",
"From the very start your base has the whole army, one of each: sky troopers, lone heavy gunner, sniper, scout, drone, raider, MLRS, mortar (plus assault squads and a tank) — possess anyone right away":"Od samog početka borbe u tvom stožeru stoji cijela vojska, po jedna jedinica: desant, teški strijelac pojedinac, snajperist, izviđač, dron, napadač, višecijevni bacač raketa, minobacač (i jurišni odredi s tenkom) — preuzmi bilo koga odmah",
"\"Custom order\" for possession (pause menu, ☰ on the phone): each class has a number, 1 is the top; ▲▼ change it, ✕ means never. After death and on X you get the unit closest to the fight in that order":"\"Vlastiti redoslijed\" preuzimanja kontrole (pauza, na telefonu ☰): svaka klasa ima broj, 1 je glavni; ▲▼ ga mijenjaju, ✕ znači nikad. Nakon pogibije i na X preuzima se vojnik najbliži borbi prema tom redoslijedu",
"Bots are no longer snipers: they miss at range, on the move, against runners and targets in cover; bullets whizz past you and kick up dirt and cover nearby. Explosions knock you down: flinch, to one knee, off your feet and back up":"Botovi više nisu snajperisti: promašuju izdaleka, u trku, trkače i one u zaklonu; pored tebe meci zvižde, udaraju u tlo i obližnji zaklon. Eksplozije te obaraju: trzaj, na koljeno, s nogu i ustajanje",
"Capture a point and a pod drops a squad and a builder. An outpost on the point upgrades along one branch: defence (MG bunker → heavy bunker with AT gun), support (repair drones → force-field dome), recon (radio scanner → sniper & spotter tower)":"Zauzmi točku i kapsula spušta odred i inženjera. Predstraža na točki nadograđuje se po jednoj grani: obrana (bunker → bunker s protutenkovskim topom), potpora (popravni dronovi → štitnik sile), izviđanje (radiosken → snajperski toranj)",
"The HQ upgrades too: armour plating, defence turrets, faster orbital drop, +25% income, global radar, comms array (+command points). The AI does the same":"Stožer se također nadograđuje: oklopne ploče, kupole, ubrzano orbitalno spuštanje, prihod +25 %, globalni radar, komunikacijske antene (+zapovjedni bodovi). AI radi isto",
"New in v7.0":"Novo u v7.0",
"Your base has one of every unit and vehicle: sky troopers, sniper, scout, drone, raider, MLRS, mortar. Select any and {0} — try them before you even build.":"U stožeru je po jedan vojnik i vozilo svake vrste: desant, snajperist, izviđač, dron, napadač, višecijevni bacač raketa, minobacač. Odaberi bilo kojeg i {0} — isprobaj ih prije izgradnje.",
"POSSESS":"PREUZMI",
"Point {0}: a builder landed with the pod. Select it and place an \"Outpost\"{1} by the point — then pick an upgrade branch.":"Točka {0}: iz kapsule se spustio inženjer. Odaberi ga i postavi \"Predstražu\"{1} kraj točke — zatim odaberi granu nadogradnji.",
"OUTPOST":"PREDSTRAŽA",
"The outpost is ready — select it and pick a branch: ⛨ Defence (MG bunker, AT bunker), ✚ Support (repair drones, force-field dome) or ◎ Recon (scanner, sniper tower). A builder nearby does the work.":"Predstraža je spremna — odaberi je i izaberi granu: ⛨ Obrana (bunker, bunker s protutenkovskim topom), ✚ Potpora (popravni dronovi, štitnik sile) ili ◎ Izviđanje (skener, snajperski toranj). Gradi inženjer u blizini.",
"UPGRADE":"NADOGRADI",
"The HQ is a \"super point\": select it{0} — armour, turrets, faster drops, +25% income, radar, comms.":"Stožer je \"super točka\": odaberi ga{0} — oklopne ploče, kupole, brže spuštanje, prihod +25 %, radar, antene.",
"☰ → \"Possession\": turn on \"Custom order\" and choose who you take after death — #1, #2… ✕ means never.":"☰ → \"Preuzimanje\": uključi \"Vlastiti redoslijed\" i odluči koga preuzimaš nakon pogibije — br. 1, br. 2… ✕ znači nikad.",
"Esc → pause → \"Custom order\": choose who you take after death and on X — #1, #2… ✕ means never.":"Esc → pauza → \"Vlastiti redoslijed\": odluči koga preuzimaš nakon pogibije i na X — br. 1, br. 2… ✕ znači nikad.",
