"The Polygon works in developer mode only":"Poligon radi samo u razvojnom načinu",
"⚔ Polygon: an endless battle at the map centre with reinforcements. X — possess a soldier there":"⚔ Poligon: bitka u središtu karte s beskonačnim pojačanjima. X — preuzmi vojnika na poligonu",
