"training complete":"trening završen",
"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Dodirni »Nišan« za približavanje. Ponovni dodir — natrag.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Tvoj odred ide za tobom. Otvori ☰ → »Pauza« → pločica »Odred sa mnom« — postat će »Djelujem sam«.",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Inženjer je odabran — dodirni »◆ Vadi kristale« na njegovoj kartici dolje (ili dodirni zelene kristale).",
"Training complete!":"Trening završen!",
"steps":"koraka",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Znaš graditi bazu, naručivati vojsku, zapovijedati i skakati u borbu. Dalje je pravi meč: Kurator će ti savjetovati tijekom igre.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Znaš se kretati, letjeti, pucati, kriti se i zapovijedati odredom. Dalje je pravi meč.",
"Real battle":"Prava bitka",
"Again":"Još jednom",
"done":"prođeno",
"you are on PC: keyboard and mouse":"igraš na PC-ju: tipkovnica i miš",
"you are on a phone: touch screen":"igraš na telefonu: zaslon osjetljiv na dodir",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Sigurna igraonica: neprijatelji su i dalje nepomične lutke, nitko ne puca na tebe. Korak se računa tek kad sam izvedeš radnju.",
"Show others (training for the other device)":"Prikaži ostale (treninzi za drugi uređaj)",
"Old training (v7.1)":"Stari trening (v7.1)",
"Back to the normal device mode":"Vrati uobičajeni način uređaja",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Trening za drugi uređaj ponovno učitava stranicu u njegovu načinu (PC — miš i tipkovnica, telefon — dodir; na PC-ju dodir lako provjeriš u Chromeu: F12 → ikona telefona).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Trening ×4: zasebni postupni treninzi „Strategija\" i „Strijelac\" za PC i za telefon. Sigurna pješčanica s lutkama, istaknuta potrebna tipka, strelice, animirane tipke, miš i geste; korak se računa samo za pravu radnju, „ponovi korak\", napredak na vrhu i nagrada na kraju",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"Izbornik Trening sam prikazuje treninge za tvoj uređaj; „Prikaži ostale\" — sva četiri na bilo kojem uređaju; „Stari trening (v7.1)\" je ostao",
"New in v7.2":"Novo u v7.2",
"NEW IN v7.2":"NOVO U v7.2",
"No grenades left":"Granate su potrošene",
"Rocket and grenade recharging · {0} s":"Raketa i granata se pune · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Lijevo — kretanje, desno — pogled · dodir po neprijatelju — raketa / granata · 2 dodira — refleks · 3 dodira — topnički udar",
"Less":"Manje",
"More":"Više",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Neprijateljska tehnika ili zgrada u blizini — dodirni je: ispalit će se raketa.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Mnogo neprijatelja — brzo dodirni 2 puta slobodno mjesto desno: refleks usporava vrijeme.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Naciljaj skupinu neprijatelja i dodirni 3 puta — topnički udar.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Lijevi palac — kretanje, desni — pogled. Nišan na neprijatelju — vatra sama.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ lijevo uz rub — jetpack: dodirni za skok, drži za let.",
"Old v7.2 layout":"Stari raspored v7.2",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Povlači prstom po desnoj polovici ekrana — ispod prsta pojavit će se štapić za pogled.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Dodirni lijevu stranu i povlači prstom — ispod prsta pojavit će se štapić. Dođi do zelene oznake.",
"Hold the \"Jet\" button at the left edge.":"Drži tipku „Jetpack\" uz lijevi rub.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Desnim štapićem naciljaj lutku — vojnik puca sam kad je nišan na meti.",
"Tap the dummy on the screen — a rocket flies.":"Dodirni lutku na ekranu — ispalit će se raketa.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Dodirni lutku — poletjet će granata (u metu, u luku).",
"Double tap an empty spot on the right quickly.":"Brzo dodirni 2 puta slobodno mjesto desno.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Lagani način za slabe telefone: manja razlučivost, bez sjena i izobličenja, upola manje botova i čestica, najviše 30 FPS; sam smanjuje razlučivost ako je FPS < 25. Na telefonu je prema zadanome uključen (Postavke → Grafika → „Lagani način\"; ili ?lite=1 / ?lite=0 u poveznici).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Telefon: novi raspored. Lijevo — kretanje, desno — pogled (oba štapića pojavljuju se ispod prsta). Samo lijevi prst — „auto\"; kad se koristi i desni, vojnik puca sam samo dok je nišan na neprijatelju. Dodir neprijatelja — raketa ili granata, 2 dodira — refleks, 3 dodira — topnički udar. Automatsko punjenje. Jetpack — tipka uz lijevi rub. Donji kutovi su slobodni, minikarta u kutu, savjeti se zatvaraju križićem, zadatak se može sklopiti. Stari raspored: Postavke → Telefon.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Savjeti (skočni i Kurator) — jedan prekidač u postavkama. Tko si (vrsta vojnika ili tehnike) — oznaka „Ti: …\" u HUD-u. Optika puške i mitraljeza je prozirna. Ploča „Arsenal\" je sidrena desno, može se sklopiti i isključiti. „Solo bez odreda\" (J) je uklonjen. Glas strategа više ne ponavlja istu repliku. Tenkovi imaju pokazivač kupole u odnosu na trup. Kursor više ne nestaje na početku treninga strategije.",
