"Voice of hints and curator":"Glas savjeta i Vodiča",
"Advanced: custom class order":"Napredno: vlastiti redoslijed klasa",
"Voice of hints & curator":"Glas savjeta i Vodiča",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Telefon: tri načina štapića. Samo lijevi — „auto\" (jak magnet, slabiji meci). Samo desni — nišan se sam uključuje, jači magnet, bolja preciznost. Oba — bez nišana, slabiji magnet i preciznost. Tipka 👁 desno skriva/vraća sučelje.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Telefon: strategija je pojednostavljena — samo inženjer i zgrade. Lijevo su kartice (inženjer, Stožer, Vojarna…): dodir — kamera leti tamo, donja traka odmah pokazuje što graditi/proizvoditi. „U borbu\" — gore lijevo. Vojska se bori sama. Cijela strategija — Postavke → Telefon.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Preuzimanje — dvije kvačice: „Odredi\" i „Tehnika\" (na telefonu je tehnika prema zadanome isključena — vozi je AI). Ako je tehnika isključena, E (na telefonu — tipka desno) pored svog vozila — sjedni za njegov top: vozilo vozi samo, ti pucaš. Stari „vlastiti redoslijed klasa\" nalazi se u „Naprednim\". Pri preuzimanju jedinica se javlja radiom.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Pametni savjeti: osnovni se sami gase nakon 2. pokretanja, ali igra će ti ukazati na funkciju koju nikad ne koristiš. Kvačice: osnovni / napredni / rijetki, zasebno — glas savjeta i Vodiča.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Refleks se puni od ubojstava (niz puni jače). Suborci su zaostali ili poginuli — strateg ti spušta nove (skuplje od uobičajenog pojačanja). Grafika i zvuk v7.2gfx su spojeni: eksplozije u kolutima, dim, krhotine, akustika okana i kratera. Datum izdanja je sada stvaran.",
