"The sky is a portal: fly up and you come out on the opposite side of the meteor.":"Nebo je portal: uzleti i izaći ćeš na suprotnoj strani meteora.",
"Follow the strategist's orders — XP for them is doubled and tripled.":"Izvršavaj naredbe stratega — iskustvo za njih se udvostručuje i utrostručuje.",
"X — instantly switch to the squad or vehicle closest to the fight.":"X — trenutno prijeđi na odred ili vozilo najbliže borbi.",
"Bullets hit hardest at medium range, 20–50 meters.":"Meci najjače pogađaju na srednjoj udaljenosti, 20–50 metara.",
