"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Karijera i spremanja ostaju netaknuti. U borbi je isti izbornik tipka „🛠 Izbornik\" gore desno{0}.",
"New developer match":"Novi razvojni meč",
"all unlocked, endless ore, instant build, arsenal":"sve otvoreno, ruda bez kraja, trenutna gradnja, arsenal",
"Trainings — all 4":"Treninzi — sva 4",
"PC and phone (strategy and shooter)":"PC i telefon (strategija i strijelac)",
"Cinema: split screen":"Kino: podijeljeni ekran",
"strategist bot left, shooter bot right":"bot strateg lijevo, bot strijelac desno",
"Cinema: everything built":"Kino: sve izgrađeno",
"both bases built and upgraded — for footage":"obje baze izgrađene i nadograđene — za snimanje",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Kino način — podijeljeni ekran: lijevo bot strateg (pogled odozgo na bazu i vojsku), desno bot strijelac iz prvog lica. Tipke dolje (i tipke S, P): „Podijeljeni ekran\" i „★ Sve izgrađeno\" — obje baze izgrađene i nadograđene za snimanje.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Jezgre i tunela kroz meteor više nema — meteor je pun, borba se vodi samo na površini.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Telefon: 👁 skriva sučelje, ali ostavlja jetpack, ⇆, štapiće i oznaku zadatka. „◎ Nišan\" (samo desni prst) — osjetno jači i širi magnet; jačina magneta za tri moda — Postavke → Kontrole → „Napredno\". Na topu vozila gumb se zove „Siđi\".",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Trening: na telefonu — samo telefonski, na PC-u — samo PC. Sva 4 su u izborniku „🛠 Razvojnik\". Razvojnički mod i Arsenal sada su jedan izbornik (u borbi — „🛠 Izbornik\" gore desno, F8 na PC-u).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Stilovi grafike „Dendy (8-bit)\" i „16-bit\": Postavke → Grafika → „Stil grafike\" (detalji — gumb ⚙). Ako je FPS u prvih ~10 s meča ispod 24, Dendy se uključuje sam (ispod 20 — veći piksel, 120 linija); obavijest „vrati normalno\" trajno vraća običnu grafiku. Tvoj izbor u izborniku uvijek ima prednost.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D modeli okoliša (ruševine, olupine, utvrde) — samo oni s dobrim ocjenama, učitavaju se po potrebi. Isključi: Postavke → Grafika → „Novi 3D modeli okoliša\".",
"New in v7.5":"Novo u v7.5",
