"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Vojnici mogu graditi: E (na telefonu „Uđi\") kod svog gradilišta — vojnik gradi sam, suborci u blizini pomažu. Ako su inženjeri zauzeti, strateg će te sam zamoliti za pomoć — oznaka „GRADILIŠTE\".",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Oznake stratega: strateg postavlja ⌖ na skupinu neprijatelja pokraj tebe — topništvo pogađa 8 s kasnije, a obližnji vlastiti MLRS „Grad\" ispaljuju plotun. Tvoj vlastiti topnički udar iz strategije također dobiva potporu „Gradova\".",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Skrovišta s oružjem u teretnim kontejnerima i srušenim satelitima (📦 vidljivo s 70 m): E — teški mitraljez na 90 s, zapaljivo streljivo ili rakete, plus pune granate. Puzanje: Ctrl — lezi / ustani (niže, mirnije ciljanje, ali sporo).",
