"Link copied":"Poveznica kopirana",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"„▶ Igraj odmah\" — prvi gumb izbornika: kratak prelet ispod neba-portala i odmah u borbu (preskakanje — bilo koja tipka ili dodir).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Pogoci se osjećaju: metalni zvuk i iskre, oznaka ubojstva uz nišan (hitac u glavu — žuta), serija ×N, glatka tresnja od eksplozija, usporeni prikaz na ključnim ubojstvima. Tresnju, usporeni prikaz i savjet možeš isključiti u Postavkama.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Rezultat meča: vrijeme, uništenja, najbolja serija, ★ MVP i najbolji odred, kartica meča — „⇪ Podijeli\", PNG ili poveznica na igru.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Savjet „što sada raditi\" slijeva ispod resursa: zapovijed stratega, točka za zauzimanje, napad Roja. ✕ ili F7 — sažmi.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Borba se sama sprema ako zatvoriš ili sakriješ karticu — „⟲ Nastavi\" u izborniku.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"Verzija v7.5 ostala je u izborniku „🕘 Verzija igre\" — ako ti se nova ne svidi. Anonimna statistika (bez imena i e-pošte) sada se šalje; isključi u Postavkama.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"„Igraj odmah\", odziv pogodaka, rezultat meča s karticom, savjet „što raditi\", automatsko spremanje",
"and older: v7.5, v7.4, milestones v1–v7.0":"i starije: v7.5, v7.4, prekretnice v1–v7.0",
"New in v7.6":"Novo u v7.6",
"NEW IN v7.6":"NOVO U v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Odabir frakcije prije meča: „Konzorcij\" (teško pješaštvo u pogonskom oklopu, oklop i topništvo) ili „Roj\" (brzina, jata dronova, teški hici s distorzijom). AI igra za drugu. Izbor se pamti.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Svaka frakcija ima svoju tehniku i jedinstvene stvari: Konzorcij — tenk „Nosorog\" i „Keramitne ploče\", Roj — „Jato dronova\" i „Fazni jetpackovi\". Balans je provjeren mečevima botova.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Krateri od eksplozija: topništvo, rakete i tenkovski topovi kopaju jame u meteoru — kroz njih možeš hodati i voziti se, a u njima se možeš skloniti.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Pogled iz trećeg lica za vojnika (V, pamti se; na telefonu — Upravljanje) i glatka kamera vozila s oznakom gdje će pogoditi top.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"Verzija v7.6 ostala je u izborniku \"🕘 Verzija igre\" za slučaj da ti se više sviđa.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Frakcije Konzorcij / Roj s izborom prije meča, krateri od eksplozija, pogled iz trećeg lica",
"and older: v7.6, v7.5, milestones v1–v7.0":"i starije: v7.6, v7.5, prekretnice v1–v7.0",
