"Anomaly ahead! The vein is singing — go around!":"Anomalija ispred! Žila pjeva — zaobilazimo!",
"Hear that hum? A singing vein. Keep clear!":"Čujete li onaj zujanje? Pjevajuća žila. Ne prilazite!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Anomalija! Zrak se vrtloži — to je vrtlog, zaobiđi!",
"Rocks floating in the air… A whirlpool! Stay out!":"Kamenje lebdi u zraku… Vrtlog! Ne ulazi!",
"Anomaly ahead — it is crackling with current!":"Anomalija ispred — prašti strujom!",
"Rods and lightning — a Crackler. It loves armour!":"Šipke i munje — Pucketač. Obožava oklop!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Anomalija! Tlo podrhtava od žege — Žeravnik!",
"Careful, a Brazier underfoot!":"Pazi, pod nogama je Žeravnik!",
"Anomaly — green mist! Acid, hold your breath!":"Anomalija — zelena magla! Kiselina, zadržite dah!",
"The mist is drifting our way, go around!":"Magla puzi prema nama, zaobilazimo!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Anomalija! Zrak je kao staklo — Leća, savija metke!",
"Everything is warping… a Lens nearby!":"Slika se iskrivljuje… Leća je blizu!",
"Ha! An enemy walked right into the anomaly!":"Ha! Neprijatelj je ušetao ravno u anomaliju!",
"Got him! Lure them into anomalies!":"Uhvaćen! Namamljuj ih u anomalije!",
"Beautiful zap! One less tin can.":"Lijepo je puklo! Jedna limenka manje.",
