"They say veins hide artifacts. Only first the vein sings…":"Kažu da žile skrivaju artefakte. Samo prvo žila zapjeva…",
"Throw a bolt first, then walk. Old habit.":"Prvo baci vijak, pa onda idi. Stara navika.",
