" — close":" — zatvori",
"Supply drop":"Kutija opskrbe",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Spušta kutiju blizu vaših snaga: streljivo, granate, rakete, dijelovi oružja, popravni komplet.",
"\"Grad\" rocket strike":"Udar \"Grada\"",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 raketa po velikoj površini za 3 sekunde — brže i šire od topničkog udara.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Podrška: kutija, izviđanje, \"Grad\", topnički udar (zatim 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"PAŽNJA: \"Grad\" Roja po vašem području!",
"Warning! Rocket salvo on our position!":"Pažnja! Raketna salva na našu poziciju!",
"take the supply crate":"uzmi kutiju opskrbe",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Anomalije na meteoru (val 1): \"Pjevajuća žila\" — svijetleći zeleni kristal koji zuji i ritmičnim impulsima udara sve u blizini; \"Vrtlog\" privlači i odbacuje, \"Pucketač\" sijeva munjama između šipki, \"Žeravnik\" planuje pod nogama, \"Kisela magla\" i \"Leća\" (savija metke i sliku) lebde uokolo.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Anomalije se osjete unaprijed (zujanje, sjaj, treperenje zraka). Isprazni ih granatom, raketom ili vijkom (E kraj anomalije): zaspat će, a ponekad ostavi artefakt s plusom i minusom. Odred upozorava preko radija, a neprijatelji (i naši) ponekad upadnu u njih — namamljuj ih!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Podrška za zapovjedne bodove: 4 u borbi (📡 na telefonu) — kutija opskrbe, izviđanje, udar \"Grada\", topnički udar po nišanu. Strateg na karti vidi anomalije tek nakon izviđanja.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Kutije opskrbe u ruševinama starih ekspedicija, kraj stožera i uz dovršene zgrade: streljivo, granate, rakete, dijelovi oružja (otključavaju dodatke).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"Verzija v7.7 ostala je u izborniku \"🕘 Verzija igre\". Anomalije se mogu isključiti u Postavkama.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomalije (\"Pjevajuća žila\" i još 5), pražnjenje vijkom i granatom, artefakti, podrška za ZB, kutije opskrbe",
"and older: v7.7, v7.6, milestones v1–v7.0":"i starije: v7.7, v7.6, prekretnice v1–v7.0",
"New in v7.8":"Novo u v7.8",
"NEW IN v7.8":"NOVO U v7.8",
"Close":"Zatvori",
"Anomalies on the meteor":"Anomalije na meteoru",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ u kutu otvara izbornik pauze: Nastavi, Počni ispočetka, Trening, Grafika, Postavke, Glavni izbornik (uz potvrdu). Telefon: ☰ gore desno (borbene radnje — pločica \"⚡ Radnje\"); PC: gumb \"☰ Izbornik\" gore desno ili Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Grafika je prema zadanim postavkama uvijek obična — Dendy samo ako ga odabereš: prekidač \"Grafika: Obična / Dendy (8-bit) / 16-bit\" nalazi se u glavnom izborniku i u pauzi. Ako igra jako zapinje, pojavljuje se savjet s gumbom \"Uključi Dendy\".",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Telefon i tablet: gumb radnje \"✋\" s desne strane pojavljuje se samo kad je u blizini nešto što možeš učiniti — \"Uzmi\" (skrovište, kutija), \"Uđi\" (vozilo, kupola, top), \"Gradi\", \"Siđi\", \"Vijak\" kraj anomalije. Možeš i samo dodirnuti istaknuti predmet.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Telefon, strategija: drži prst ~0,3 s (telefon zavibrira, pojavi se žuti prsten) i povuci — okvir za odabir; obično povlačenje pomiče kameru. Postoji i gumb \"Okvir\" s desne strane; u treningu korak \"Okvir\" priznaje i odabir odreda dodirom.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Telefon: sitne gumbe lakše je pogoditi, popis podrške 📡 je veći, strateške ploče više ne prekrivaju pauzu i rezultate. Verzija v7.8 ostala je u izborniku \"🕘 Verzija igre\".",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"Izbornik ☰ na telefonu i PC-ju, bez automatskog Dendyja, gumb \"✋\" na dodir, odabir okvirom na telefonu",
"16-bit":"16-bit",
"Lagging? Try the Dendy graphics — they are lighter.":"Zapinje? Probaj Dendy grafiku — lakša je.",
