"Pause: resume, restart, training, graphics, settings, main menu":"Pauza: nastavi, ispočetka, trening, grafika, postavke, glavni izbornik",
"Menu: pause, restart, training, graphics, settings":"Izbornik: pauza, ispočetka, trening, grafika, postavke",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Drži prst na tlu ~0,3 s — telefon zavibrira i pojavi se žuti prsten — pa, ne puštajući, povuci: nastat će okvir. Ili gumb \"Okvir\" s desne strane. Može i običan dodir po odredu.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Za puni zaslon na iPhoneu: \"Podijeli\" ⬆ → \"Dodaj na početni zaslon\" — igra će se otvoriti bez Safarijevih traka.",
"Open portal-meteor.pages.dev for that.":"Za to otvori stranicu portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Dodir — odaberi · dodir po tlu — idi · drži — izbornik zapovijedi · drži i povuci — okvir · 2 prsta — zumiranje",
"Robo-ninja":"Robo-nindža",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Junakinja-ubojica: skokovi-teleporti, katana, shurikeni. Sama skače po neprijateljskim zonama i siječe robote. 1 po strani.",
"Shadow protocol":"Protokol \"Sjena\"",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Istraživanje: otključava robo-nindžu u Vojarni. Potrebna je dovršena tvornica mehova.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Junakinja (1 po strani): sama se teleportira po neprijateljskim zonama i siječe robote; možeš je preuzeti i igrati ručno.",
"is ready. She works on her own (AUTO) — possess her to play manually":"je spremna. Radi sama (AUTO) — preuzmi je da igraš ručno",
"Robo-ninja ready for action":"Robo-nindža spremna je za borbu",
