"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ DVOBOJ NINDŽI! Blok neposredno prije udarca je parada, juriš je izbjegavanje. Pazi na bljesak zamaha",
"The two ninjas have met in a duel!":"Dvije nindže sučelile su se u dvoboju!",
"⚔ Duel won! Our ninja prevails":"⚔ Dvoboj dobiven! Naša nindža je jača",
