"Teleport: aim at the ground (up to 150 m)":"Teleport: nišani u tlo (do 150 m)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AUTO: sama skače po neprijateljskim zonama i siječe. Joystick / WASD — pauza 1,5 s",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Ručno: dodir po neprijatelju — juriš i udarac, povlačenje — zamah, 🛡 — blok",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Ručno upravljanje: lijeva tipka miša — katana, desna tipka miša — blok, Shift — probijanje, Q — shurikeni, G — teleport",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Nindža: dodir po neprijatelju — juriš i udarac, povlačenje s desne — zamah, ● — udarac, 🛡 — blok (na vrijeme = parija), ⇑ — probijanje, ✦ — shurikeni, ◎ — teleport, AUTO — sama",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Nindža: lijeva tipka miša — katana (drži — težak udarac), desna tipka miša — blok (na vrijeme = parija), Shift/Z — probijanje, Q — shurikeni, G — teleport do nišana, skok u zraku — dvostruki skok / trčanje po zidu, {0} — AUTO",
