"LMB — strike (hold — heavy) · RMB — block · Shift — blink · Q — shurikens · G — teleport":"lijeva tipka miša — udarac (drži — težak) · desna tipka miša — blok · Shift — probijanje · Q — shurikeni · G — teleport",
