"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Radio Portal Meteor: 100+ pjesama EDMITRY-ja izravno u igri — gumb 📻 (PC: tipka 5, [ ] — pjesma). Glazba se učitava putem mreže i ne opterećuje igru; glasnoća i automatsko pokretanje u postavkama, plus poveznica „Slušaj na Spotifyju“.",
