"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 desno — Radio Portal Meteor: glazba EDMITRY-ja dok se boriš.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Radio Portal Meteor: glazba EDMITRY-ja dok se boriš. [ ] — pjesma.",
"Radio Portal Meteor (EDMITRY): volume":"Radio Portal Meteor (EDMITRY): glasnoća",
"Radio: start by itself in battle":"Radio: samostalno se uključuje u borbi",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-nindža: kiborg s katanom. Otključava se u Vojarni istraživanjem „Protokol Sjena“ (potrebna tvornica mehova). Sama se teleportira u neprijateljske zone, siječe neprijatelje na komade (bez krvi — iskre), probija se, baca shurikene, vodi dvoboje s neprijateljskom nindžom. Preuzmi je — način AUTO ili ručno upravljanje (na telefonu — vlastiti gumbi).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Radio Portal Meteor: 103 pjesme EDMITRY-ja izravno u igri. Tipka 5 (može se promijeniti), na telefonu — ☰ → Postavke → Zvuk. Glasnoća i „samostalno uključivanje u borbi“ nalaze se u postavkama; glazba se stišava na eksplozijama i ispod glasa radija.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Novi jezici: uzbečki i tadžički — potpuno; kineski, španjolski, portugalski — djelomično. Novi odabir jezika u izborniku pored „Novi meč“.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Telefon: „sakrij ikone“ 👁 skuplja preostale gumbe u uredan stupac uz desni rub; portret se više ne preklapa; iPhone — igra se ne sukobljava s gestama Safarija, a „Podijeli → Dodaj na početni zaslon“ pokreće je preko cijelog zaslona.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Iz v7.8.1: izbornik ☰ u kutu (pauza, ispočetka, trening, grafika), bez automatskog Dendyja, gumb radnje ✋ na telefonu. v7.8.1 i v7.8 ostali su u izborniku „🕘 Verzija igre“.",
"Robo-ninja, EDMITRY radio, Uzbek and Tajik, phone and iPhone UX":"Robo-nindža, radio EDMITRY, uzbečki i tadžički, praktičnije na telefonu i iPhoneu",
