"Veterans deployed: {0} {1} · lv {2} · battles {3}":"Veterani u stroju: {0} {1} · razina {2} · bitaka {3}",
"Squad {0} is lost — its veterancy (lv {1}) is gone. See \"My squads → Fallen\".":"Odred {0} je izgubljen — veteranstvo (razina {1}) je nestalo. Vidi „Moji odredi → Pali“.",
"{0}: level {1} — perk \"{2}\" ({3})":"{0}: razina {1} — perk „{2}“ ({3})",
"battles":"bitaka",
"since":"od",
"MY SQUADS":"MOJI ODREDI",
"Veterancy carries over between battles. A squad earns XP (infantry 1, building 2, vehicle 3), levels, stars and perks. Veterans deploy first in a new battle. A lost squad loses everything and joins the Fallen.":"Veteranstvo se prenosi iz bitke u bitku. Odred skuplja iskustvo (pješaštvo 1, zgrada 2, vozilo 3), dobiva razine, zvjezdice i perkove. U novoj bitci veterani se postrojavaju prvi. Izgubljeni odred gubi sve i odlazi među Pale.",
"Active":"U stroju",
"Empty for now — squads get names in your next battle.":"Za sada je prazno — odredi dobivaju imena već u prvoj bitci.",
