"Living world: requests, hero quests, breakthrough ops":"Živi svijet: zahtjevi svojih, zadaci heroja, probojne operacije",
"Living world":"Živi svijet",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Svoji traže pomoć i nagrađuju, heroji daju zadatke, a zapelu frontu probija operacija",
"A request":"Zahtjev",
"Breakthrough":"Proboj",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Svoji ponekad traže pomoć: poziv preko radija, kartica \"ZAHTJEV\" i oznaka ✋. Vod je prikovan — uništi neprijatelje kraj njega. Nagrada: vojnik kapsulom iz baze, oružje iz prtljažnika buggyja, mjesto strijelca ili orbitalno pokrivanje. Ne treba ti — ✕ ili samo ignoriraj.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Veteran-izviđač \"Sova\" nudi zadatak. Y — prihvati (N — odbij). Idi do oznake ★, ukloni stražu i stoj kraj pilota 3 s — pridružit će se tvom odredu.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Fronta je zapela — stožer nudi proboj. Y — prihvati. Drži repetitor 8 s bez neprijatelja u blizini: neprijateljska karta bit će otkrivena 60 s. Generator — neprijateljski topovi utihnu na 2 min. U Strategu — \"Dodijeli odred\". Neprijatelj to također može: pazi na ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Svoji traže pomoć: kartica \"ZAHTJEV\" i oznaka ✋. Uništi neprijatelje kraj prikovanog odreda — dobit ćeš nagradu. ✕ — preskoči.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Heroj \"Sova\" nudi zadatak — dodirni \"Prihvati\". Idi do ★, ukloni stražu, stoj kraj pilota.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Fronta je zapela — dodirni \"Prihvati\" i drži repetitor 8 s: neprijateljska karta otvorit će se na minutu.",
