"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"Glavni borbeni tenk: top i mitraljez. Konzorcijev \"Buldog\" je čvršći, Rojev \"Pauk\" je brži.",
