"Autonomous flying gunner: fast, fragile, fears anti-air.":"Autonomni leteći strijelac: brz, krhak, boji se protuzračne obrane.",
"Upgrade":"Nadogradnja",
"Longer, faster jetpacks for all infantry.":"Jetpackovi dalje i brže za svo pješaštvo.",
"Extractors mine more ore.":"Ekstraktori vade više rude.",
"Army-wide levels: less damage taken / more damage dealt.":"Razine za cijelu vojsku: manje primljene štete / veća nanesena šteta.",
"Levels":"Razina",
"Base":"Baza",
"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Srce baze: vodovi, graditelji, kapsule, istraživanja. Gubitak stožera znači poraz.",
"Produces: ":"Proizvodi: ",
"Launch pad":"Lansirna rampa",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Silos kraj stožera: odavde kroz nebeski portal polijeću kapsule, sanduci opskrbe i bombarderi. Na njoj se ne može graditi.",
"Economy":"Ekonomija",
"Key building":"Ključna zgrada",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Slaba točka — stražnji dio (motor): šteta ×{0}. Top, 2 mitraljeske kupole, raketni modul; vrlo sporo se okreće — napadni s boka.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Slaba točka — užareno jezgro ispod trbuha: šteta odozdo ×{0}. Zraka izobličenja i udar po površini; prekoračuje barijere — drži razmak, ne stoj u gomili.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Protiv: zračne bombe i topništvo (×{0}), rakete (×{1}), tepih-bombardiranje; meci ga jedva grebu (×{2}).",
"Faction":"Frakcija",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Brzi strojevi, jata dronova, tuneli i regeneracija. Pješaštvo je lakše, ali brže; topovi i tračnice jače udaraju.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Teško pješaštvo u oklopu s pogonom, betonske barijere, popravak i topništvo. Sporije, ali čvršće.",
