"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"2. Igraj i razmišljaj naglas: što je nejasno, što smeta, što je zabavno. Kut zaslona prikazuje verziju, vrijeme i FPS — po njima se snimka usklađuje s bilješkama.",
